# Chronos Academy - anos/bimestres + historico recolhido + busca
Set-Location "$HOME\Documents\chronos-academy"
git status --short
New-Item -ItemType Directory -Force "$HOME\Documents\backups-chronos" | Out-Null
Invoke-WebRequest -UseBasicParsing -Uri "https://firestore.googleapis.com/v1/projects/controle-de-aulas-c2973/databases/(default)/documents/chronos/dados_escola" -OutFile "$HOME\Documents\backups-chronos\dados_escola_REST_2026-09-24.json"
Get-Item "$HOME\Documents\backups-chronos\dados_escola_REST_2026-09-24.json" | Select-Object Name, Length
$b64 = @'

'@
$b64 | python -c "import base64,zlib,sys; exec(compile(zlib.decompress(base64.b64decode(sys.stdin.read())).decode('utf-8'),'instalador','exec'))"
if ($LASTEXITCODE -eq 0) { npm run build }
if ($LASTEXITCODE -eq 0) {
  git add src/utils/bimestres.js src/pages/Turma.jsx src/pages/Admin.jsx
  git commit -m "Aulas por ano/bimestre sem editar codigo, historico recolhido e busca de aulas"
  git push origin main
}
